{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In rhesus monkeys, the glycosylated nucleoside GAZT showed a CSF/plasma ratio of only 0.04 at 1 h, 10-fold lower than AZT and AMT, directly demonstrating that glycosylation and polar character severely restrict CNS access; the query is a much larger polyglycosylated macrocycle, so this barrier phenotype transfers strongly.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "68Ga-PSMA-11 (947 Da) showed no brain uptake in humans, attributed to its molar mass exceeding the 400–500 Da BBB limit; the query has a far higher molecular weight and multiple polar substituents, supporting failure to achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A sulfonated adenosine derivative was undetectable in mouse brain (<0.1% of plasma level) despite measurable plasma exposure, showing that polar/ionizable glycoside-like molecules are effectively excluded from the CNS; the query contains multiple sugars, a carboxylate, and numerous polar groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Orientin, a flavonoid glucoside, showed only low brain levels after intravenous administration in rats due to high polarity; the query is far more polar and heavily glycosylated, making poor BBB penetration highly likely.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a multi-glycoside flavonol, was the least concentrated compound in rat brain and could hardly pass the blood-brain barrier; the query shares and exceeds this multi-glycoside, high-polarity character.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a very large, heavily glycosylated, polycyclic peptide with multiple sugars, a carboxylate, and numerous polar/ionizable groups. All transferable experimental evidence from glycosylated and polar molecules consistently demonstrates poor or negligible CNS penetration, and the query is structurally even more extreme, so meaningful CNS access is predicted to fail.",
  "evidence_gaps": [
    "No direct CNS measurement exists for the exact query molecule.",
    "Transporter-mediated efflux status is unknown, but the strong physicochemical exclusion already supports the fail prediction.",
    "All cited evidence comes from smaller glycosides/polar compounds; however, their consistent poor penetration and the query's larger size and polarity make the direction robust."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

